        sums.append(sums[-1]+i)
    @lru_cache(None)
    def dp(i,j):
        if j-i==1:
            return True
        for k in range(i+1,j):
            if k!=j-1 and sums[j]-sums[k]<m:
                continue
            if k!=i+1 and sums[k]-sums[i]<m:
                continue
            if dp(i,k) and dp(k,j):return True
        return False
    return dp(0,len(nums))

